import os
import queue
import sys
import threading
import time

import pyaudio
from deepgram import DeepgramClient, LiveTranscriptionEvents, LiveOptions


class MicrophoneStream:
    def __init__(self, rate=16000, chunk=1024, channels=1, format=pyaudio.paInt16):
        self.rate = rate
        self.chunk = chunk
        self.channels = channels
        self.format = format
        self._audio = pyaudio.PyAudio()
        self._buffer = queue.Queue()
        self._stream = None
        self.closed = True

    def __enter__(self):
        self._stream = self._audio.open(
            format=self.format,
            channels=self.channels,
            rate=self.rate,
            input=True,
            frames_per_buffer=self.chunk,
            stream_callback=self._fill_buffer,
        )
        self.closed = False
        self._stream.start_stream()
        return self

    def __exit__(self, exc_type, exc, tb):
        self.close()

    def _fill_buffer(self, in_data, frame_count, time_info, status_flags):
        self._buffer.put(in_data)
        return None, pyaudio.paContinue

    def generator(self):
        while not self.closed:
            try:
                data = self._buffer.get(timeout=0.1)
            except queue.Empty:
                continue
            if data is None:
                return
            yield data

    def close(self):
        if self.closed:
            return
        self.closed = True
        if self._stream is not None:
            self._stream.stop_stream()
            self._stream.close()
        self._stream = None
        self._buffer.put(None)
        self._audio.terminate()


def stream_transcripts():
    api_key = os.environ["DEEPGRAM_API_KEY"]
    dg_client = DeepgramClient(api_key)
    connection = dg_client.listen.websocket.v("1")

    done = threading.Event()

    def on_open(self, open_event, **kwargs):
        print("Connection opened", file=sys.stderr)

    def on_transcript(self, result, **kwargs):
        try:
            alt = result.channel.alternatives[0]
            transcript = alt.transcript
            if not transcript:
                return
            if result.is_final:
                print(transcript, flush=True)
            else:
                print(transcript, end="\r", flush=True)
        except Exception:
            pass

    def on_error(self, error, **kwargs):
        print(f"Error: {error}", file=sys.stderr)
        done.set()

    def on_close(self, close_event, **kwargs):
        done.set()

    connection.on(LiveTranscriptionEvents.Open, on_open)
    connection.on(LiveTranscriptionEvents.Transcript, on_transcript)
    connection.on(LiveTranscriptionEvents.Error, on_error)
    connection.on(LiveTranscriptionEvents.Close, on_close)

    options = LiveOptions(
        model="nova-2",
        language="en-US",
        encoding="linear16",
        sample_rate=16000,
        channels=1,
        interim_results=True,
        punctuate=True,
        smart_format=True,
    )

    if not connection.start(options):
        raise RuntimeError("Failed to start Deepgram streaming connection")

    with MicrophoneStream(rate=16000, chunk=1024) as mic:
        try:
            for data in mic.generator():
                connection.send(data)
                if done.is_set():
                    break
        except KeyboardInterrupt:
            pass
        finally:
            try:
                connection.finish()
            except Exception:
                pass

    while not done.is_set():
        time.sleep(0.05)


if __name__ == "__main__":
    stream_transcripts()
